INSERT INTO tblKPI_AuditDiscrepancies (PeriodKey, ScopeID, AuditCode, Category, Title, PrimarySource, PrimaryValue, SecondarySource, SecondaryValue, VarianceAnalysis, ActionOwner, VerificationStatus) VALUES
('2026-09', 'MNLK', 'MISMATCH_01', 'MISMATCH', N'Chênh lệch Sĩ số & Rút học MN Long Khánh', N'Báo cáo vận hành: 129/166 HS (77.7%) · Rút học 61%', N'129 HS (61% rút)', N'Báo cáo trường: 122/182 HS (67%) · Tái ghi danh 94.6%', N'122 HS (94.6% tái ghi danh)', N'Tỷ lệ rút học 61% mâu thuẫn trực tiếp với tỷ lệ tái ghi danh 94.6% của MN Long Khánh. Cần thống nhất lại công thức tính mẫu số công suất (166 hay 182 phòng).', N'Hiệu Trưởng MN Long Khánh & Khối Vận Hành', 'PENDING_VERIFY'),
('2026-09', 'ALL', 'MISMATCH_02', 'MISMATCH', N'Vênh trạng thái triển khai Phần mềm CNTT', N'Báo cáo Vận hành: Ghi nhận CRM và Phân hệ Thu phí đã hoàn thành', N'Hoàn thành', N'Báo cáo CNTT: Xếp trong danh mục chờ duyệt/chuyển tiếp; CRM tuyển sinh theo dõi Excel Sheet 8', N'Chờ duyệt (Excel Staging)', N'Phân hệ Ngân sách và CRM đang chạy song song trên Excel Sheet 8 TVTS Tracking. Cần phân biệt rõ trạng thái phần mềm thử nghiệm và phần mềm chính thức đưa vào khai thác.', N'Bộ Phận CNTT & Phòng Tuyển Sinh', 'CONFIRMED'),
('2026-09', 'ALL', 'MISMATCH_03', 'PARADOX', N'Nghịch lý Khảo sát Hài lòng cao nhưng Rút học thật', N'Khảo sát Đảm bảo chất lượng QA: 93.6% Phụ huynh hài lòng mức Đạt trở lên', N'93.6% Hài lòng', N'Dữ liệu SIS chốt sổ: Lũy kế Tháng 9 có 53 học sinh rút hồ sơ (21 ca tiện đón, 10 ca kinh tế)', N'53 HS rút hồ sơ (1.98%)', N'Khảo sát sự hài lòng rất cao (Cấp 1-2-3 hài lòng 100%, Mầm non 91%) nhưng 53 HS vẫn rút. Cỡ mẫu khảo sát 65 PH có thể chưa đại diện đúng tuyến xe và khối lớp có HS rút học.', N'Bộ Phận QA & Ban Giám Hiệu', 'PENDING_VERIFY'),
('2026-09', 'ALL', 'MISMATCH_04', 'MISMATCH', N'Mâu thuẫn số liệu Kỷ luật lao động & Thôi việc', N'Báo cáo chi tiết: Ghi nhận 0 trường hợp kỷ luật lao động trong toàn trường', N'0 kỷ luật', N'Báo cáo điều hành: Ghi nhận 1 trường hợp tại MNLK (gian lận) và 1 nhân viên CSVC thôi việc do mâu thuẫn', N'2 trường hợp', N'Cần đối soát danh sách quyết định kỷ luật chính thức của Phòng Nhân sự để đồng bộ với báo cáo giám sát của Hội đồng trường.', N'Phòng Tổ Chức - Nhân Sự', 'RESOLVED'),
('2026-09', 'ALL', 'MISMATCH_05', 'BOTTLENECK', N'Tồn đọng sửa chữa CSVC & Hiệu quả xe đưa rước', N'Yêu cầu CSVC: Tiếp nhận 79 yêu cầu, còn 4 ticket điều hòa/máy chiếu tồn đọng chậm xử lý', N'4 ticket tồn', N'Hiệu quả xe bus: Biên LN đạt 12.6% (định mức 15%), tỷ lệ lấp đầy ghế 78%', N'Biên LN 12.6%', N'18 máy lạnh hỏng tập trung tại Khu B (10 máy) và Khu C (7 máy) làm phụ huynh phàn nàn và ảnh hưởng tỷ lệ rút học vì xe bus/CSVC.', N'Ban Quản Trị CSVC & Tổ Xe Bus', 'CONFIRMED');
INSERT INTO tblKPI_PeriodNarratives (PeriodKey, DomainCode, ScopeID, Heading, ContentText, DirectiveAction) VALUES
('2026-09', 'CLUB', 'ALL', N'Đánh giá hiệu quả Câu lạc bộ ngoại khóa Tháng 9', N'Tiểu học vượt chỉ tiêu CLB (117.7%, tăng hơn 30 HS). MN Long Khánh đạt 93% (Tiền tiểu học, Nhảy hiện đại). MN Biên Hòa chỉ đạt 64% (cần giảm lớp vẽ, tăng Tiếng Anh kịch nghệ & Aerobic). Cấp Trung học không mở được 2 lớp Lập trình Game và Cờ vua do thiếu học sinh.', N'Sắp xếp CLB vào tiết cuối sau giờ học để tăng tỷ lệ tham gia.'),
('2026-09', 'HEALTH', 'ALL', N'Cảnh báo dịch bệnh học đường & Khử khuẩn Tiểu học', N'Bệnh lý chủ đạo: Tập trung vào nhóm đau đầu, đau bụng chưa rõ nguyên nhân (135 lượt), Tai mũi họng 234 lượt và 53 ca sốt. Cuối tháng 9 ghi nhận nhiều ca bị Cúm A tại Tiểu học khối 4 và 5 cần theo dõi và khử khuẩn khẩn cấp.', N'Khử khuẩn lớp học khối 4 & 5, truyền thông phòng bệnh Cúm A và Đau mắt đỏ.'),
('2026-09', 'LEAVE', 'ALL', N'Phân tích áp lực nghỉ phép nhân viên đầu năm học', N'2 tháng đầu năm học ghi nhận tổng cộng 470 lượt nghỉ và 551 ngày nghỉ từ 198 nhân viên. Khối Mầm non (82.5 ngày) và Bộ phận Bếp (54 ngày) có khối lượng nghỉ cao nhất.', N'Bố trí nhân sự tăng cường và phụ bếp dự phòng tránh ảnh hưởng chất lượng bán trú.'),
('2026-09', 'MAINTENANCE', 'ALL', N'Tình hình bảo trì thang máy và sửa chữa thiết bị', N'Tháng 9 ghi nhận 79 yêu cầu sửa chữa (Máy lạnh 18, PC 9, Tivi 8, Quạt 7...). Đã bảo trì thang máy MN Long Khánh.', N'Hoàn thành dứt điểm 4 ticket tồn đọng máy lạnh Khu B và C trong tuần đầu tháng 10.');
